package nexusbench

// Location is where an image of the data set lives: "docker-hosted" or "upstream".
type Location string

// The two places the data set puts an image.
const (
	// LocationHosted is the docker-hosted repository of the bench Nexus.
	LocationHosted Location = "docker-hosted"
	// LocationUpstream is the registry the docker-proxy repository mirrors.
	LocationUpstream Location = "upstream"
)

// DatasetImage is one image of the fixed data set.
type DatasetImage struct {
	Name, Tag   string
	Location    Location
	PullThrough bool   // pulled once through docker-proxy by Seed
	Digest      string // manifest digest, sha256:...
}

// datasetTable is the fixed data set of DEVDESK-505 (D-I), in order. The digests
// are not written here: Dataset computes them from the generator, so a change of
// the generator can never leave a stale value behind.
var datasetTable = []DatasetImage{
	{Name: "api", Tag: "1.0.0", Location: LocationHosted},
	{Name: "api", Tag: "1.1.0", Location: LocationHosted},
	{Name: "team/api", Tag: "1.0.0", Location: LocationHosted},
	{Name: "tools/cli", Tag: "0.1.0", Location: LocationHosted},
	// The same name and tag in both places, with different contents: a read
	// through the group says which member answered.
	{Name: "shared/base", Tag: "1.0", Location: LocationHosted},
	{Name: "shared/base", Tag: "1.0", Location: LocationUpstream},
	{Name: "mirror/cached", Tag: "1.0", Location: LocationUpstream, PullThrough: true},
	{Name: "mirror/uncached", Tag: "1.0", Location: LocationUpstream},
}

// Dataset returns the fixed data set, in order, with the manifest digest of every
// image filled from the layout generator. The slice is a copy.
func Dataset() []DatasetImage {
	images := make([]DatasetImage, len(datasetTable))
	for i, img := range datasetTable {
		img.Digest = imageDigest(img)
		images[i] = img
	}
	return images
}
package nexusbench

import (
	"context"
	"errors"
	"net/http"
	"net/url"
	"strings"
)

const (
	// componentsPath lists the components of a repository.
	componentsPath = restAPI + "/components"
	// maxComponentPages bounds a listing: a continuation token that never ends
	// is an error after this many calls, not an endless loop.
	maxComponentPages = 1000
	// manifestMarker is what the path of a Docker manifest asset holds:
	// v2/<name>/manifests/<tag>.
	manifestMarker = "/manifests/"

	// upCheck is what a missing admin password asks the operator to do.
	upCheck = "run `mise run nexus-bench:up` to provision the bench"
)

// component is one image tag a repository lists: the image name, the tag and,
// when the instance lists it, the digest of the manifest ("sha256:<hex>").
type component struct {
	Name    string
	Version string
	Digest  string
}

// adminFromStore returns a client authenticated with the stored admin password
// and the stored secrets. It never reads the initial password of the pod: seed,
// restore and reset need a bench that up already provisioned. It sends no
// request, so a stored password the instance refuses shows on the first call.
func adminFromStore(ctx context.Context, baseURL string, store SecretStore) (*client, Secrets, error) {
	if err := ctx.Err(); err != nil {
		return nil, Secrets{}, &transportError{Op: "read the stored admin password", Err: err}
	}
	sec, found, err := store.Load()
	if err != nil {
		return nil, Secrets{}, &BenchError{
			Kind:  ProvisionFailed,
			Cause: "the secrets file of the bench cannot be read",
			Check: "check the permissions and the content of the secrets file, then " + upCheck,
			Err:   err,
		}
	}
	if !found || sec.AdminPassword == "" {
		return nil, Secrets{}, &BenchError{
			Kind:  ProvisionFailed,
			Cause: "the bench has no admin password stored: it was never provisioned, or its provisioning did not finish",
			Check: upCheck,
			Err:   errors.New("no admin password in the secrets file"),
		}
	}
	return newClient(baseURL, adminUserID, sec.AdminPassword), sec, nil
}

// componentPage is one page of GET /v1/components.
type componentPage struct {
	Items             []componentItem `json:"items"`
	ContinuationToken *string         `json:"continuationToken"`
}

type componentItem struct {
	Name    string           `json:"name"`
	Version string           `json:"version"`
	Assets  []componentAsset `json:"assets"`
}

type componentAsset struct {
	Path     string `json:"path"`
	Checksum struct {
		SHA256 string `json:"sha256"`
	} `json:"checksum"`
}

// listComponents lists the components of repo, following the continuation token
// until the last page; a token equal to the previous one is an error. A
// repository the instance does not know lists as no component. An error on any
// page drops what the earlier pages returned.
//
// H-COMPONENTS (to settle at step 12): a Docker component is one image tag, and
// the sha256 checksum of its asset under v2/<name>/manifests/<tag> is the digest
// of the manifest.
func (c *client) listComponents(ctx context.Context, repo string) ([]component, error) {
	op := "list the components of " + repo
	var out []component
	token := ""
	for page := 0; page < maxComponentPages; page++ {
		query := url.Values{"repository": {repo}}
		if token != "" {
			query.Set("continuationToken", token)
		}
		var body componentPage
		found, err := c.get(ctx, op, componentsPath, query, &body)
		if err != nil {
			return nil, err
		}
		if !found {
			if page == 0 {
				return nil, nil
			}
			return nil, &APIError{Op: op, Status: http.StatusNotFound}
		}
		for _, item := range body.Items {
			out = append(out, component{Name: item.Name, Version: item.Version, Digest: manifestDigest(item)})
		}
		if body.ContinuationToken == nil || *body.ContinuationToken == "" {
			return out, nil
		}
		// The same token as the previous page would repeat that page for ever.
		if *body.ContinuationToken == token {
			return nil, &decodeError{Op: op, Err: errors.New("the continuation token repeats")}
		}
		token = *body.ContinuationToken
	}
	return nil, &decodeError{Op: op, Err: errors.New("the continuation token never ends")}
}

// manifestDigest returns "sha256:<hex>" of the manifest asset of item, or "" when
// the instance lists none. The asset of the tag itself wins over any other
// manifest asset (a digest-addressed one, for instance).
func manifestDigest(item componentItem) string {
	digest := ""
	for _, a := range item.Assets {
		if a.Checksum.SHA256 == "" || !strings.Contains(a.Path, manifestMarker) {
			continue
		}
		if strings.HasSuffix(a.Path, manifestMarker+item.Version) {
			return "sha256:" + a.Checksum.SHA256
		}
		if digest == "" {
			digest = "sha256:" + a.Checksum.SHA256
		}
	}
	return digest
}
package nexusbench

import (
	"context"
	"fmt"
	"io"
	"slices"
	"time"
)

// upstreamPollInterval separates two rounds of the wait for the upstream. It is
// shorter than pollInterval: a registry is ready within seconds of its image
// being local, and the wait has no host to probe.
const upstreamPollInterval = 2 * time.Second

// UpstreamState is what the cluster says about the bench upstream registry.
type UpstreamState int

// The states of the upstream, from the least to the most alive.
const (
	// UpstreamMissing: the Deployment bench-upstream does not exist.
	UpstreamMissing UpstreamState = iota
	// UpstreamCut: the Deployment exists with zero replicas.
	UpstreamCut
	// UpstreamStarting: one replica is wanted and no pod of it is ready yet.
	UpstreamStarting
	// UpstreamReady: a pod of the upstream that is not terminating is ready.
	UpstreamReady
)

// ReadUpstream reads the state of the bench upstream with read-only kubectl
// calls: it writes nothing and waits for nothing. A pod that fails to pull is
// Starting, not an error: diagnosing is the job of the wait. It runs no
// preflight; the caller does. Every failure is a *BenchError, but a cancelled
// context, which is returned as is.
func ReadUpstream(ctx context.Context, r Runner, p Params) (UpstreamState, error) {
	d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", out: io.Discard}
	return d.readUpstream(ctx)
}

// EnsureUpstream brings the bench upstream to one ready replica, and returns
// when it is ready or fails with a diagnosis. It reads first and writes only
// when the upstream is cut: one scale to one replica, then the wait. A starting
// upstream is waited for without a write; a ready one is left alone. The
// Deployment itself is applied by Deploy, so a missing one is an error. A
// custom upstream (Params.UpstreamIsBench is false) is refused before any call:
// the bench scales what it deploys and nothing else. The wait polls the pods
// and the claim of the upstream only, until Params.Timeout. It runs no
// preflight; the caller does. Every failure is a *BenchError, but a cancelled
// context, which is returned as is. A nil out discards the progress lines.
func EnsureUpstream(ctx context.Context, r Runner, clk Clock, p Params, out io.Writer) error {
	if out == nil {
		out = io.Discard
	}
	if !p.UpstreamIsBench() {
		return customUpstreamError(p)
	}
	// The runner of a test may ignore ctx; the first call must not depend on it.
	if err := ctx.Err(); err != nil {
		return err
	}
	d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", clk: clk, out: out}
	state, err := d.readUpstream(ctx)
	if err != nil {
		return err
	}
	switch state {
	case UpstreamMissing:
		return &BenchError{
			Kind:  Unclassified,
			Cause: fmt.Sprintf("the Deployment %s does not exist in namespace %q", upstreamDeployment, p.Namespace),
			Check: "run `mise run nexus-bench:up`, which applies it, or " + d.pf.command("get", "deployment", upstreamDeployment, "-n", p.Namespace),
		}
	case UpstreamReady:
		d.say("the upstream is ready")
		return nil
	case UpstreamCut:
		d.say("scaling the upstream to one replica")
		if err := d.scaleUpstream(ctx, 1); err != nil {
			return err
		}
	case UpstreamStarting:
		d.say("the upstream is starting")
	}
	return d.waitUpstream(ctx)
}

// customUpstreamError refuses an upstream the bench does not deploy.
func customUpstreamError(p Params) *BenchError {
	return &BenchError{
		Kind: Unclassified,
		Cause: fmt.Sprintf("%s points at an upstream the bench did not deploy in namespace %q, and the bench scales only its own upstream",
			envUpstreamURL, p.Namespace),
		Check: "unset " + envUpstreamURL + " to use the bench upstream, or start and stop your own upstream registry yourself",
	}
}

// readUpstream is ReadUpstream on a deployer.
func (d *deployer) readUpstream(ctx context.Context) (UpstreamState, error) {
	var dep struct {
		Spec struct {
			Replicas *int `json:"replicas"`
		} `json:"spec"`
	}
	args := []string{"get", "deployment", upstreamDeployment, "-n", d.pf.p.Namespace, "-o", "json"}
	found, err := d.fetch(ctx, "read the Deployment "+upstreamDeployment, args, &dep, true)
	if err != nil {
		return UpstreamMissing, err
	}
	if !found {
		return UpstreamMissing, nil
	}
	// The manifest leaves the count out, so the API server defaults it to one.
	if dep.Spec.Replicas != nil && *dep.Spec.Replicas == 0 {
		return UpstreamCut, nil
	}
	var pods struct {
		Items []podObject `json:"items"`
	}
	if err := d.read(ctx, "read the "+d.w.name+" pod", d.podsArgs(), &pods); err != nil {
		return UpstreamMissing, err
	}
	if slices.ContainsFunc(pods.Items, podObject.ready) {
		return UpstreamReady, nil
	}
	return UpstreamStarting, nil
}

// scaleUpstream is the one write of EnsureUpstream. A failed write is not
// retried: the scale is not what a second try would fix.
func (d *deployer) scaleUpstream(ctx context.Context, replicas int) error {
	args := []string{"scale", "deployment/" + upstreamDeployment, fmt.Sprintf("--replicas=%d", replicas), "-n", d.pf.p.Namespace, applyTimeout}
	_, errOut, err := d.pf.r.Run(ctx, nil, args...)
	if err == nil {
		return nil
	}
	if cerr := ctx.Err(); cerr != nil {
		return cerr
	}
	return d.pf.failure("scale the Deployment "+upstreamDeployment, args, string(errOut), err)
}

// waitUpstream polls until a pod of the upstream is ready, a diagnosis fails the
// run, or the deadline passes. Like the wait of Deploy, it looks at the deadline
// after a round, so the cluster is read once more at the very end.
func (d *deployer) waitUpstream(ctx context.Context) error {
	deadline := d.clk.Now().Add(d.pf.p.Timeout)
	for {
		obs, err := d.round(ctx)
		if err != nil {
			return err
		}
		if err := ctx.Err(); err != nil {
			return err
		}
		if slices.ContainsFunc(obs.pods, podObject.ready) {
			d.say("the upstream is ready")
			return nil
		}
		if !d.clk.Now().Before(deadline) {
			return d.upstreamDeadline(obs)
		}
		if err := d.clk.Sleep(ctx, upstreamPollInterval); err != nil {
			return err
		}
	}
}

// upstreamDeadline is the end of a wait that ran out of time. A pending reading
// that was still there says more than the deadline does.
func (d *deployer) upstreamDeadline(obs observation) error {
	if d.candidate != nil {
		return d.candidate
	}
	p := d.pf.p
	return &BenchError{
		Kind:  Deadline,
		Cause: fmt.Sprintf("the upstream %s was not ready within %s; last state: %s", upstreamDeployment, p.Timeout, obs.describe()),
		Check: describePodCommand(p, d.w) + ", then raise " + envTimeout + " if the image pull or the start is only slow",
	}
}

// ready reports whether the pod is not terminating and its Ready condition is
// True.
func (pod podObject) ready() bool {
	if pod.Metadata.DeletionTimestamp != nil {
		return false
	}
	for _, c := range pod.Status.Conditions {
		if c.Type == "Ready" {
			return c.Status == "True"
		}
	}
	return false
}
package nexusbench

import (
	"context"
	"time"
)

// Clock is the time the waits of the bench read and spend. Tests swap it for a
// fake that never waits, so no test sleeps for real.
type Clock interface {
	// Now returns the current time.
	Now() time.Time
	// Sleep waits for d, or until ctx is done. It returns ctx.Err() when ctx is
	// done, before sleeping if it already was, and nil after the whole wait. A
	// duration of zero or less returns at once (after the ctx check).
	Sleep(ctx context.Context, d time.Duration) error
}

// realClock is the Clock of the command: the wall clock.
type realClock struct{}

// NewClock returns the real clock.
func NewClock() Clock { return realClock{} }

// Now implements Clock.
func (realClock) Now() time.Time { return time.Now() }

// Sleep implements Clock.
func (realClock) Sleep(ctx context.Context, d time.Duration) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if d <= 0 {
		return nil
	}
	timer := time.NewTimer(d)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}
package nexusbench

import (
	"regexp"
	"strings"
)

// ErrKind says which of the failures of the bench (D-F) a BenchError is. The
// zero value is Unclassified on purpose: an error nobody classified must not
// pass for the first named kind.
type ErrKind int

// The kinds of D-F, in the order the bench meets them.
const (
	// Unclassified is a failure none of the other kinds describes.
	Unclassified ErrKind = iota
	KubectlMissing
	ContextNotFound
	ClusterUnreachable
	Forbidden
	NamespaceForeign
	NamespaceMissing
	NodePortTaken
	AdmissionDenied
	PodPending
	ImagePull
	Crash
	Deadline
	RESTUnreachable
	ProvisionFailed
	// The kinds of DEVDESK-505, appended so no earlier value moves.
	SkopeoMissing
	RegistryUnreachable
	RegistryRefused
	SeedFailed
)

// BenchError is the one error type of the bench: a probable cause and what to
// check, both in English and both free of secrets. Err is the underlying error,
// kept for errors.Is and errors.As; Error never prints it, because the text of
// a failed sub-process can carry a credential.
type BenchError struct {
	Kind  ErrKind
	Cause string
	Check string
	Err   error
}

// Error returns "<Cause>. Check: <Check>".
func (e *BenchError) Error() string {
	return e.Cause + ". Check: " + e.Check
}

// Unwrap returns the underlying error, or nil when there is none.
func (e *BenchError) Unwrap() error { return e.Err }

// classifyKubectl maps the stderr of a failed kubectl call to a kind. The text
// of kubectl changes between versions, so this is a fallback for the cases the
// structured calls (exit status, JSON) cannot tell apart; a text it does not
// know is Unclassified.
func classifyKubectl(stderr string) ErrKind {
	s := strings.ToLower(stderr)
	switch {
	// The more specific reason wins: a webhook refusal is reported by the API
	// server as Forbidden too.
	case strings.Contains(s, "admission webhook") && strings.Contains(s, "denied"):
		return AdmissionDenied
	case strings.Contains(s, "provided port is already allocated"),
		strings.Contains(s, "provided port is not in the valid range"):
		return NodePortTaken
	case strings.Contains(s, "forbidden"):
		return Forbidden
	case strings.Contains(s, "unable to connect to the server"),
		strings.Contains(s, "connection refused"),
		strings.Contains(s, "i/o timeout"),
		strings.Contains(s, "tls handshake timeout"):
		return ClusterUnreachable
	}
	return Unclassified
}

// isNotFound reports whether stderr is the kubectl answer for an absent object.
func isNotFound(stderr string) bool {
	return strings.Contains(stderr, "(NotFound)")
}

// status403 matches a 403 that is a whole number, so a port such as 40399 in
// the text of an error is not read as a refusal.
var status403 = regexp.MustCompile(`\b403\b`)

// classifySkopeo maps the stderr of a failed skopeo call to a kind. Like
// classifyKubectl it reads text that changes between versions, so it is a
// fallback: a text it does not know is Unclassified. The stderr is only read
// here; it is never put in a message.
func classifySkopeo(stderr string) ErrKind {
	s := strings.ToLower(stderr)
	switch {
	case strings.Contains(s, "connection refused"),
		strings.Contains(s, "no such host"),
		strings.Contains(s, "i/o timeout"):
		return RegistryUnreachable
	// "authentication required" is what skopeo says for a push to a registry
	// that wants a login and was given none: no "unauthorized" appears.
	case strings.Contains(s, "unauthorized"),
		registryDenied(s),
		strings.Contains(s, "authentication required"),
		status403.MatchString(s):
		return RegistryRefused
	case strings.Contains(s, "manifest unknown"):
		return SeedFailed
	}
	return Unclassified
}

// registryDenied reads the two wordings a registry refusal takes, "denied: ..."
// and "requested access to the resource is denied". A bare "denied" is not
// enough: skopeo says "permission denied" for a local folder it cannot write,
// which is not a registry that refused. s is lower case.
func registryDenied(s string) bool {
	s = strings.ReplaceAll(s, "permission denied", "")
	return strings.Contains(s, "denied:") || strings.Contains(s, "access to the resource is denied")
}

package nexusbench

import (
	"context"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"time"
)

// ImageRef names an image for skopeo: Transport is "oci", "dir" or "docker".
// For docker, Location is "<host[:port]>/<name>[:tag]" without the "//".
type ImageRef struct{ Transport, Location string }

// CopyOptions are the options of one copy.
type CopyOptions struct {
	SrcCreds, DestCreds *Credentials // nil = --*-no-creds
	PreserveDigests     bool
}

// Credentials is a user and a password for one registry. It prints as
// "[REDACTED]" under every fmt verb and in every slog handler, so neither a log
// line nor an error built with %v can carry the password.
type Credentials struct {
	User     string
	Password string `json:"-"`
}

const redactedCredentials = "Credentials{User: <redacted>, Password: REDACTED"

// String implements fmt.Stringer.
func (Credentials) String() string { return redactedCredentials }

// GoString implements fmt.GoStringer.
func (Credentials) GoString() string { return redactedCredentials }

// Format implements fmt.Formatter, so no verb (not even %d or %x, which a
// Stringer does not cover) can print the fields.
func (Credentials) Format(f fmt.State, _ rune) { _, _ = f.Write([]byte(redactedCredentials)) }

// LogValue implements slog.LogValuer.
func (Credentials) LogValue() slog.Value { return slog.StringValue("[REDACTED]") }

// ImageCopier copies images between registries and layouts.
type ImageCopier interface {
	Copy(ctx context.Context, src, dst ImageRef, o CopyOptions) error
	ManifestDigest(ctx context.Context, ref ImageRef, creds *Credentials) (string, error)
}

const (
	// skopeoStderrMax is how much of the stderr of skopeo is kept for the
	// classifier; the text never reaches a message.
	skopeoStderrMax = 64 << 10
	// manifestMax is the largest manifest ManifestDigest reads (the limit
	// registries apply themselves is 4 MiB).
	manifestMax = 4 << 20
	// skopeoKillDelay bounds the wait for skopeo's output pipes once it is
	// killed, in case a child it started still holds them.
	skopeoKillDelay = 2 * time.Second

	// policyAcceptAnything is the policy file of every call: skopeo refuses to
	// run without a readable policy on a host that has none, and the bench has
	// no signature to check. The default rule is the whole policy.
	policyAcceptAnything = `{"default":[{"type":"insecureAcceptAnything"}]}`
)

// skopeoCopier runs the skopeo found on PATH. It is, with kubectl.go and
// secrets.go, one of the three files of the package that start a process.
type skopeoCopier struct{ path string }

// NewSkopeoCopier finds skopeo on PATH. It fails with a SkopeoMissing BenchError
// when skopeo is not installed.
func NewSkopeoCopier() (ImageCopier, error) {
	path, err := exec.LookPath("skopeo")
	if err != nil {
		return nil, &BenchError{
			Kind:  SkopeoMissing,
			Cause: "skopeo was not found on PATH",
			Check: "install skopeo with your package manager, then run `skopeo --version`",
			Err:   err,
		}
	}
	return &skopeoCopier{path: path}, nil
}

// Copy implements ImageCopier: `skopeo copy` of src to dst. A docker reference
// whose host is not the loopback is refused before any process starts.
func (c *skopeoCopier) Copy(ctx context.Context, src, dst ImageRef, o CopyOptions) error {
	if err := checkSide(src, o.SrcCreds); err != nil {
		return err
	}
	if err := checkSide(dst, o.DestCreds); err != nil {
		return err
	}
	w, err := newSkopeoWorkdir()
	if err != nil {
		return err
	}
	defer w.remove()

	args := []string{"--policy", w.policy, "copy"}
	if o.PreserveDigests {
		args = append(args, "--preserve-digests")
	}
	for _, side := range []struct {
		flagPrefix string
		ref        ImageRef
		creds      *Credentials
	}{{"--src-", src, o.SrcCreds}, {"--dest-", dst, o.DestCreds}} {
		flags, err := w.sideFlags(side.flagPrefix, side.ref, side.creds)
		if err != nil {
			return err
		}
		args = append(args, flags...)
	}
	args = append(args, imageArg(src), imageArg(dst))

	if _, err := c.run(ctx, w, "copy", args, 0); err != nil {
		return err
	}
	return nil
}

// ManifestDigest implements ImageCopier: the sha256 of the raw manifest of ref,
// computed here from `skopeo inspect --raw`, not read from anything skopeo says
// about it.
func (c *skopeoCopier) ManifestDigest(ctx context.Context, r ImageRef, creds *Credentials) (string, error) {
	if err := checkSide(r, creds); err != nil {
		return "", err
	}
	w, err := newSkopeoWorkdir()
	if err != nil {
		return "", err
	}
	defer w.remove()

	flags, err := w.sideFlags("--", r, creds)
	if err != nil {
		return "", err
	}
	args := append([]string{"--policy", w.policy, "inspect", "--raw"}, flags...)
	args = append(args, imageArg(r))

	manifest, err := c.run(ctx, w, "inspect", args, manifestMax)
	if err != nil {
		return "", err
	}
	if len(manifest) == 0 {
		return "", &BenchError{
			Kind:  SeedFailed,
			Cause: "skopeo printed no manifest",
			Check: "run `skopeo inspect --raw` on the same reference by hand",
		}
	}
	sum := sha256.Sum256(manifest)
	return "sha256:" + hex.EncodeToString(sum[:]), nil
}

// run starts skopeo with args in the environment of w and returns its stdout
// (at most stdoutMax bytes; with 0 the stdout is dropped). Nothing skopeo prints
// reaches the error: the stderr only picks its kind.
func (c *skopeoCopier) run(ctx context.Context, w *skopeoWorkdir, op string, args []string, stdoutMax int) ([]byte, error) {
	cmd := exec.CommandContext(ctx, c.path, args...) //nolint:gosec // the binary is the skopeo found on PATH and the references were checked by checkSide
	cmd.Env = skopeoEnvironment(w.registriesConf)
	cmd.WaitDelay = skopeoKillDelay
	stdout, stderr := newCapWriter(stdoutMax), newCapWriter(skopeoStderrMax)
	cmd.Stdout, cmd.Stderr = stdout, stderr

	runErr := cmd.Run()
	if runErr == nil {
		if stdoutMax > 0 && stdout.over {
			return nil, &BenchError{
				Kind:  SeedFailed,
				Cause: "the manifest is larger than the 4 MiB registries accept",
				Check: "run `skopeo inspect --raw` on the same reference by hand",
			}
		}
		return stdout.buf.Bytes(), nil
	}
	if ctxErr := ctx.Err(); ctxErr != nil {
		kind := Unclassified
		if errors.Is(ctxErr, context.DeadlineExceeded) {
			kind = Deadline
		}
		return nil, &BenchError{
			Kind:  kind,
			Cause: fmt.Sprintf("skopeo %s was interrupted", op),
			Check: "run the command again",
			Err:   ctxErr,
		}
	}
	return nil, skopeoFailure(op, classifySkopeo(stderr.buf.String()), runErr)
}

// skopeoFailure builds the error of a skopeo that exited with a failure.
func skopeoFailure(op string, kind ErrKind, runErr error) *BenchError {
	be := &BenchError{Kind: kind, Err: runErr}
	switch kind {
	case RegistryUnreachable:
		be.Cause = fmt.Sprintf("skopeo %s could not reach a registry", op)
		be.Check = "check that the port-forward is running and the registry answers on its port"
	case RegistryRefused:
		be.Cause = fmt.Sprintf("a registry refused the skopeo %s", op)
		be.Check = "check the bench credentials in the secrets file and the privileges of the account"
	case SeedFailed:
		be.Cause = fmt.Sprintf("skopeo %s did not find the image", op)
		be.Check = "check that the image and its tag exist in the source registry"
	default:
		be.Cause = fmt.Sprintf("skopeo %s failed", op)
		be.Check = "run the same skopeo command by hand to see what it says"
	}
	return be
}

// imageArg is how skopeo is given an ImageRef: docker://<location>, or
// <transport>:<location>.
func imageArg(r ImageRef) string {
	if r.Transport == "docker" {
		return "docker://" + r.Location
	}
	return r.Transport + ":" + r.Location
