package nexusbench

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"time"
)

type SeedDeps struct {
	Runner    Runner
	Forwarder PortForwarder
	Copier    ImageCopier
	Clock     Clock
	Store     SecretStore
}

type SeedResult struct{ Images []DatasetImage }

func seedErr(cause, check string, err error) *BenchError {
	return &BenchError{Kind: SeedFailed, Cause: cause, Check: check, Err: err}
}

func wrapSeed(op string, err error) error {
	var be *BenchError
	if errors.As(err, &be) {
		return err
	}
	return seedErr(op+" failed", "run the command again", err)
}

func Seed(ctx context.Context, d SeedDeps, baseURL string, p Params, out io.Writer) (SeedResult, error) {
	if out == nil {
		out = io.Discard
	}
	c, sec, err := adminFromStore(ctx, baseURL, d.Store)
	if err != nil {
		return SeedResult{}, err
	}
	defer c.closeIdle()
	if sec.PullPassword == "" {
		return SeedResult{}, &BenchError{Kind: ProvisionFailed, Cause: "no bench-pull password", Check: upCheck}
	}
	admin := &Credentials{User: adminUserID, Password: REDACTED
	pull := &Credentials{User: pullUserID, Password: REDACTED
	if !p.UpstreamIsBench() {
		return SeedResult{}, seedErr("the upstream is not the bench upstream: "+envUpstreamURL, "unset it", nil)
	}
	state, err := ReadUpstream(ctx, d.Runner, p)
	if err != nil {
		return SeedResult{}, err
	}
	switch state {
	case UpstreamCut:
		return SeedResult{}, seedErr("the upstream is cut", "restore it", nil)
	case UpstreamMissing:
		return SeedResult{}, seedErr("the upstream does not exist", upCheck, nil)
	case UpstreamStarting:
		return SeedResult{}, seedErr("the upstream is not ready", "wait", nil)
	}
	tmp, err := os.MkdirTemp("", "devdesk-seed-")
	if err != nil {
		return SeedResult{}, wrapSeed("create folder", err)
	}
	defer os.RemoveAll(tmp)
	images := Dataset()
	layout := filepath.Join(tmp, "layout")
	if err := os.Mkdir(layout, 0o700); err != nil {
		return SeedResult{}, wrapSeed("create folder", err)
	}
	refs, err := WriteLayout(layout, images)
	if err != nil {
		return SeedResult{}, wrapSeed("write layout", err)
	}
	fmt.Fprintln(out, "seed: layout written")
	ensure := func(ref ImageRef, creds *Credentials, img DatasetImage, i int) error {
		got, err := d.Copier.ManifestDigest(ctx, ref, creds)
		if err != nil {
			var be *BenchError
			if !(errors.As(err, &be) && be.Kind == SeedFailed) {
				return wrapSeed("read", err)
			}
		} else if got == img.Digest {
			return nil
		}
		fmt.Fprintf(out, "seed: copying %s:%s\n", img.Name, img.Tag)
		return wrapSeed("copy", d.Copier.Copy(ctx, ImageRef{Transport: "oci", Location: layout + ":" + refs[i]}, ref, CopyOptions{DestCreds: creds, PreserveDigests: true}))
	}
	local, stop, err := d.Forwarder.Forward(ctx, p.Namespace, "bench-upstream", 5000)
	if err != nil {
		return SeedResult{}, wrapSeed("port-forward", err)
	}
	if !loopbackRegistry(local) {
		_ = stop()
		return SeedResult{}, seedErr("the port-forward is not on the loopback", "x", nil)
	}
	for i, img := range images {
		if img.Location != LocationUpstream {
			continue
		}
		if err := ensure(upstreamImageRef(local, img), nil, img, i); err != nil {
			_ = stop()
			return SeedResult{}, err
		}
	}
	_ = stop()
	for i, img := range images {
		if img.Location != LocationHosted {
			continue
		}
		if err := ensure(nexusImageRef(p, dockerHostedRepository, img), admin, img, i); err != nil {
			return SeedResult{}, err
		}
	}
	cachedNow := map[string]string{}
	comps, err := c.listComponents(ctx, dockerProxyRepository)
	if err != nil {
		return SeedResult{}, wrapSeed("list", err)
	}
	for _, comp := range comps {
		cachedNow[comp.Name+":"+comp.Version] = comp.Digest
	}
	for _, img := range images {
		if !img.PullThrough || cachedNow[nameTag(img)] == img.Digest && cachedNow[nameTag(img)] != "" {
			continue
		}
		tgt := filepath.Join(tmp, "pull")
		if err := wrapSeed("pull", d.Copier.Copy(ctx, nexusImageRef(p, dockerProxyRepository, img), ImageRef{Transport: "dir", Location: tgt}, CopyOptions{SrcCreds: pull, PreserveDigests: true})); err != nil {
			return SeedResult{}, err
		}
	}
	for _, repo := range []string{dockerHostedRepository, dockerProxyRepository} {
		if err := waitListing(ctx, d.Clock, c, repo, images); err != nil {
			return SeedResult{}, err
		}
	}
	return SeedResult{Images: images}, nil
}

func waitListing(ctx context.Context, clk Clock, c *client, repo string, images []DatasetImage) error {
	want := map[string]string{}
	for _, img := range images {
		if (repo == dockerHostedRepository && img.Location == LocationHosted) || (repo == dockerProxyRepository && img.PullThrough) {
			want[nameTag(img)] = img.Digest
		}
	}
	deadline := clk.Now().Add(30 * time.Second)
	for {
		comps, err := c.listComponents(ctx, repo)
		if err != nil {
			return seedErr("list "+repo, "check", err)
		}
		seen := 0
		for _, comp := range comps {
			d, ok := want[comp.Name+":"+comp.Version]
			if !ok {
				return seedErr(repo+" holds images outside the dataset", "run `mise run nexus-bench:reset`", nil)
			}
			if comp.Digest != "" && comp.Digest != d {
				return seedErr(repo+" digest differs", "reset", nil)
			}
			seen++
		}
		if seen == len(want) {
			return nil
		}
		if !clk.Now().Before(deadline) {
			return seedErr(repo+" does not list the images", "wait", nil)
		}
		if err := clk.Sleep(ctx, 2*time.Second); err != nil {
			return err
		}
	}
}

func nexusImageRef(p Params, repository string, img DatasetImage) ImageRef {
	return ImageRef{Transport: "docker", Location: fmt.Sprintf("127.0.0.1:%d/%s/%s:%s", p.HTTPNodePort, repository, img.Name, img.Tag)}
}

func upstreamImageRef(local string, img DatasetImage) ImageRef {
	return ImageRef{Transport: "docker", Location: local + "/" + img.Name + ":" + img.Tag}
}
EOF
cd ../.. && go test -count=1 ./internal/nexusbench/ -run Seed 2>&1 | head -60

