		want := filepath.Join(t.TempDir(), "elsewhere.json")
		t.Setenv("NEXUS_BENCH_DESCRIPTOR", want)
		if got := DescriptorPath(); got != want {
			t.Errorf("DescriptorPath() = %q, want %q", got, want)
